-- Virtual cards: encrypted details vault + server-side lifecycle
-- (Workstream B, CEO order 2026-10-26).
--
-- AUDIT TRUTH this builds on (live-verified 2026-10-26 against
-- project paymentgetway):
--   * public.virtual_cards has 21 columns and NO column holding a
--     full PAN or CVV. create-virtual-card reveals both once, in the
--     creation response, and stores only masked_number + expiry_date.
--   * The PAN is platform-generated by public.generate_card_number():
--     fixed prefix '5399' + 11 random digits + a Luhn check digit.
--     It is NOT issuer-backed: no issuer BIN was ever allocated to
--     this platform, and the Mastercard Processing path (migration
--     20261107) is dark unless MASTERCARD_ENV is set. The public
--     'Coming soon' + admin-only gate therefore stays exactly as-is.
--   * The legacy public.encrypt_card_data / secure_encrypt_card_data
--     helpers are one-way SHA hashes with a literal 'salt_key' — not
--     encryption and not reversible — so they are NOT used here.
--   * RLS gap (known since 2026-10-22, worse than page-gating): the
--     live policy "Users can update own card settings" (FOR UPDATE,
--     USING auth.uid() = user_id) lets any owner PATCH ANY column of
--     their card row directly — including balance — with no
--     server-side check. This migration removes it. All card writes
--     now go through service-role edge functions
--     (create-virtual-card, fund-virtual-card, manage-virtual-card)
--     that check ownership + role themselves. The admin policy
--     "System can manage cards" (has_role admin, DB-enforced) and
--     the owner SELECT policies are untouched.
--
-- VAULT DESIGN:
--   * New cards store an AES-256-GCM envelope of {pan, cvv} in
--     details_ciphertext + details_iv. The key (CARD_VAULT_KEY)
--     exists ONLY as an edge-function secret — never in the DB,
--     never readable by anon/authenticated, never in a repo file.
--     vault_key_version supports future key rotation.
--   * has_vaulted_details is a generated flag so clients can branch
--     the honest UI state ("shown once at creation, can't be shown
--     again") for legacy cards WITHOUT the ciphertext ever leaving
--     the database in a list/detail response.
--   * Terminating a card wipes its envelope (manage-virtual-card
--     sets the ciphertext columns to NULL), so a cancelled card's
--     secrets cease to exist.
--
-- AUDIT: public.card_access_audit records every reveal attempt and
-- lifecycle action served by manage-virtual-card. RLS is enabled
-- with NO policies and table privileges revoked from anon and
-- authenticated: only service_role (edge functions) can write or
-- read it.

ALTER TABLE public.virtual_cards
  ADD COLUMN IF NOT EXISTS details_ciphertext TEXT;

ALTER TABLE public.virtual_cards
  ADD COLUMN IF NOT EXISTS details_iv TEXT;

ALTER TABLE public.virtual_cards
  ADD COLUMN IF NOT EXISTS vault_key_version INTEGER;

ALTER TABLE public.virtual_cards
  DROP COLUMN IF EXISTS has_vaulted_details;

ALTER TABLE public.virtual_cards
  ADD COLUMN has_vaulted_details BOOLEAN
  GENERATED ALWAYS AS (details_ciphertext IS NOT NULL) STORED;

-- Close the direct-DB write gap: owners keep read access; every
-- write is a checked service-role path from here on.
DROP POLICY IF EXISTS "Users can update own card settings" ON public.virtual_cards;

CREATE TABLE IF NOT EXISTS public.card_access_audit (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  card_id UUID NOT NULL REFERENCES public.virtual_cards(id) ON DELETE CASCADE,
  user_id UUID NOT NULL,
  action TEXT NOT NULL,
  success BOOLEAN NOT NULL,
  ip_address TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_card_access_audit_card
  ON public.card_access_audit (card_id, created_at DESC);

ALTER TABLE public.card_access_audit ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public.card_access_audit FROM anon, authenticated;
